/// <summary>
/// Extension class for <c>CustVendExternalItem</c> table.
/// Provides additional find logic for external item records.
/// </summary>
[ExtensionOf(tableStr(CustVendExternalItem))]
final class AVARUMCustVendExternalItemTbl_Extension
{
}

Method.Source:
/// <summary>
/// Finds a <c>CustVendExternalItem</c> record by natural key.
/// If no record is found for the provided <paramref name="_inventDimId"/>,
/// the method retries with a blank InventDimId.
/// </summary>
/// <param name="_itemId">The item ID to search for.</param>
/// <param name="_inventDimId">The inventory dimension ID to search for.</param>
/// <param name="_moduleType">The module type (Invent, Purch, Sales, Vend, CustGroup).</param>
/// <param name="_custVendRelation">The customer/vendor relation value.</param>
/// <param name="_forUpdate">Whether to select the record for update.</param>
/// <returns>
/// The found <c>CustVendExternalItem</c> record, or null if not found.
/// </returns>
static public CustVendExternalItem find_AVA(ItemId _itemId, InventDimId _inventDimId, ModuleInventPurchSalesVendCustGroup _moduleType, CustVendRel _custVendRelation, boolean _forUpdate = false)
{
    CustVendExternalItem custVendExternalItem;
    CustVendExternalItem searchParameters;

    searchParameters.ItemId = _itemId;
    searchParameters.InventDimId = _inventDimId;
    searchParameters.ModuleType = _moduleType;
    searchParameters.CustVendRelation = _custVendRelation;

    custVendExternalItem = CustVendExternalItem::findByNaturalKey(searchParameters, _forUpdate);

    if (!custVendExternalItem && searchParameters.InventDimId != InventDim::inventDimIdBlank())
    {
        searchParameters.InventDimId  = InventDim::inventDimIdBlank();
        custVendExternalItem = CustVendExternalItem::findByNaturalKey(searchParameters, _forUpdate);
    }

    return custVendExternalItem;
}
